7	public class SubcategoryPropertyQueryService(AppDbContext db)
8	{
9	    public async Task<List<PropertyFilterOptionDto>> GetPropertyFilterOptionsAsync(
10	        string subcategoryId,
11	        CancellationToken cancellationToken = default)
12	    {
13	        var definitions = await db.PropertyDefinitions
14	            .AsNoTracking()
15	            .Where(d => d.SubcategoryId == subcategoryId)
16	            .OrderBy(d => d.Name)
17	            .Select(d => new { d.Id, d.Name })
18	            .ToListAsync(cancellationToken);
