21	
22	        var values = await db.ProductProperties
23	            .AsNoTracking()
24	            .Where(pp => definitionIds.Contains(pp.PropertyDefinitionId))
25	            .Select(pp => new { pp.PropertyDefinitionId, pp.Value })
26	            .Distinct()
27	            .ToListAsync(cancellationToken);
28	
29	        var valuesByDefinition = values.ToLookup(v => v.PropertyDefinitionId, v => v.Value);
30	
31	        return definitions
32	            .Select(d => new PropertyFilterOptionDto
33	            {
34	                Name = d.Name,
35	                Values = valuesByDefinition[d.Id].OrderBy(v => v).ToList()
36	            })
37	            .ToList();
38	    }
