      this.loading.set(true);
      this.notFound.set(false);
      this.error.set(false);

      this.productsApi.getProduct(id).subscribe({
        next: (product) => {
          if (this.id() !== id) {
            return;
          }
          this.product.set(product);
          this.loading.set(false);
        },
        error: (err) => {
          if (this.id() !== id) {
            return;
          }
          this.loading.set(false);
          if (err?.status === 404) {
            this.notFound.set(true);
          } else {
            this.error.set(true);
          }
        },
      });
    });
  }
}

